// WF26 v3 - Despeja o CONTEUDO CRU (HTML, sem remover tags) dos chamados de formulario
// recentes, para ver como o GLPI renderiza a resposta do campo "perfil de referencia".
// Objetivo: descobrir se o campo de usuario (dropdown) vem como link com o users_id
// (ex: user.form.php?id=123) -> aÃ­ o WF20 extrai o ID e resolve o login (Opcao A).
const helpers = this.helpers;
const baseV1 = 'https://suporte.araraquara.sp.gov.br/api.php/v1';
const appToken = $('Carregar Tokens').first().json.app_token;
const userToken = $('Carregar Tokens').first().json.user_token;

async function callRaw(method, url, headers) {
  const resp = await helpers.httpRequest({ method, url, headers, json: false, returnFullResponse: true, ignoreHttpStatusErrors: true, skipSslCertificateValidation: true });
  let parsed = resp.body;
  if (typeof parsed === 'string') { try { parsed = JSON.parse(parsed); } catch (_) {} }
  return { status: resp.statusCode || resp.status, body: parsed };
}

const r0 = await callRaw('GET', `${baseV1}/initSession`, { 'App-Token': appToken, 'Authorization': `user_token ${userToken}` });
if (r0.status !== 200 || !r0.body || !r0.body.session_token) {
  return [{ json: { etapa: 'initSession', status: r0.status, body: r0.body } }];
}
const H = { 'App-Token': appToken, 'Session-Token': r0.body.session_token };

// Janela de 24h
const desde = new Date(Date.now() - 24 * 60 * 60 * 1000).toISOString().replace('T', ' ').substring(0, 19);
const params = [
  'criteria[0][field]=15',
  'criteria[0][searchtype]=morethan',
  `criteria[0][value]=${encodeURIComponent(desde)}`,
  'forcedisplay[0]=2',
  'forcedisplay[1]=1',
  'forcedisplay[2]=21',
  'forcedisplay[3]=15',
  'range=0-49',
  'sort=15',
  'order=DESC'
].join('&');

const r = await callRaw('GET', `${baseV1}/search/Ticket?${params}`, H);
const data = (r.body && r.body.data) ? r.body.data : (Array.isArray(r.body) ? r.body : []);
try { await callRaw('GET', `${baseV1}/killSession`, H); } catch (_) {}

const result = [];
for (const t of data) {
  const name = t['1'] || '';
  if (!name.startsWith('Solicitacao - ')) continue;
  const content = t['21'] || '';
  // recorta o trecho ao redor de "perfil" (se existir) para facilitar a leitura
  let trecho_perfil = '';
  const idx = content.toLowerCase().indexOf('perfil');
  if (idx !== -1) trecho_perfil = content.substring(Math.max(0, idx - 40), idx + 400);
  result.push({
    ticket_id: t['2'],
    name,
    date_creation: t['15'],
    tem_link_user: /user\.form\.php\?id=\d+/i.test(content) || /users_id/i.test(content),
    trecho_perfil,
    content_raw: content
  });
}

if (!result.length) return [{ json: { aviso: 'Nenhum chamado "Solicitacao - " nas ultimas 24h. Abra um chamado de teste e rode de novo.', total_tickets_janela: data.length } }];
return result.map(x => ({ json: x }));
